SINA_SMART["viro1-diagnosis"] = {"lecture":"viro1-diagnosis","title":"Laboratory diagnosis of viral infections","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-diagnosis:e0","text":"Three approaches: isolation, direct detection, indirect (serology).","topic":"Why virology labs matter now","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e1","text":"Right specimen, right time; transport at 4 °C, do not freeze enveloped viruses.","topic":"The specimen","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e2","text":"Cell culture with cytopathic effect: historical gold standard.","topic":"Virus isolation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e3","text":"Antigen tests: fast, no live virus needed (EIA, IF, rapid tests).","topic":"Direct detection","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e4","text":"HBsAg and HIV p24 are antigens detected by ELISA.","topic":"Direct detection","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e5","text":"PCR: denaturation, annealing, extension; RT step for RNA viruses.","topic":"Direct detection","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e6","text":"Real-time PCR: Ct inversely proportional to viral load.","topic":"Direct detection","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e7","text":"Sequencing detects resistance and genotypes.","topic":"Direct detection","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-diagnosis:e8","text":"IgM = recent infection; IgG = past infection or immunity; rising IgG = recent.","topic":"Serology","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"sm66s3":"a","171yjsf":"a","wh2de4":"a","wjkicu":"a","11eafhk":"a","f7k3vx":"a","1ft4m45":"a","8ayhbb":"a","1efq0d3":"a","vfg43k":"a","1f6dj0q":"a","oy2gzg":"x","137nhlk":"x"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-diagnosis:e0":{"s":0,"u":["Three approaches: isolation, direct detection, indirect (serology).","There are three approaches: virus isolation , direct detection (antigen, particle or genome) and indirect detection (antibody response)."],"dp":[]},"viro1-diagnosis:e1":{"s":1,"u":["Right specimen, right time; transport at 4 °C, do not freeze enveloped viruses.","For the doctor, choosing the specimen is the most important step: the right specimen (e.g. nasopharyngeal swab, CSF, stool, vesicle fluid, blood on EDTA for PCR), taken at the right time (early, when viral shedding is highest), and stored and transported correctly : sent quickly in secure bags; if delayed overnight kept at 4 °C, not frozen , because freezing destroys enveloped viruses."],"dp":[]},"viro1-diagnosis:e2":{"s":2,"u":["Cell culture with cytopathic effect: historical gold standard.","Cell culture , used since the 1960s, is the gold standard for isolation: the processed specimen is inoculated onto susceptible cells and observed for days or weeks for a cytopathic effect (CPE) , then confirmed by antigen or genome detection."],"dp":[]},"viro1-diagnosis:e3":{"s":3,"u":["Antigen tests: fast, no live virus needed (EIA, IF, rapid tests).","Antigen detection gives results within hours and does not need live virus: immunofluorescence , immunoperoxidase , and enzyme immunoassays (rapid lateral-flow tests for SARS-CoV-2, influenza, RSV, rotavirus, norovirus; manual ELISA for circulating antigens such as HBsAg and HIV p24 ; automated chemiluminescence)."],"dp":[{"h":"Why a negative rapid antigen test does not rule out infection","t":"Rapid antigen tests need a lot of viral protein in the sample. Early in infection, late in recovery, or with a poor swab, the amount may be below their detection limit while PCR, which amplifies a few copies millions of times, is still positive. That is why a negative rapid test in a symptomatic patient is often repeated or confirmed by PCR, while a positive rapid test is usually trusted."}]},"viro1-diagnosis:e4":{"s":3,"u":["HBsAg and HIV p24 are antigens detected by ELISA.","Antigen detection gives results within hours and does not need live virus: immunofluorescence , immunoperoxidase , and enzyme immunoassays (rapid lateral-flow tests for SARS-CoV-2, influenza, RSV, rotavirus, norovirus; manual ELISA for circulating antigens such as HBsAg and HIV p24 ; automated chemiluminescence)."],"dp":[]},"viro1-diagnosis:e5":{"s":3,"u":["PCR: denaturation, annealing, extension; RT step for RNA viruses.","Nucleic acid detection : extraction (organic, silica, magnetic beads), then PCR : denaturation (94-98 °C), annealing (50-60 °C), extension (72 °C) with a thermostable polymerase; RNA viruses need a reverse transcription step first."],"dp":[]},"viro1-diagnosis:e6":{"s":3,"u":["Real-time PCR: Ct inversely proportional to viral load.","Real-time PCR measures fluorescence each cycle; the Ct value is inversely proportional to viral load and is used to monitor HIV, HBV and HCV treatment."],"dp":[]},"viro1-diagnosis:e7":{"s":3,"u":["Sequencing detects resistance and genotypes.","Sequencing (Sanger or next-generation) detects drug resistance, determines genotype and tracks epidemics."],"dp":[]},"viro1-diagnosis:e8":{"s":4,"u":["IgM = recent infection; IgG = past infection or immunity; rising IgG = recent.","IgG appears after 10-14 days and may last for life: it indicates past infection or immunity, and a significant rise between paired sera (acute and convalescent) indicates recent infection.","IgM appears within 7-14 days and may persist for a month or more after clearance: it indicates recent infection ."],"dp":[]}},"meta":{"sm66s3":{"a":"recall","vg":"viro1-diagnosis:e2/recall/1"},"171yjsf":{"a":"application","vg":"viro1-diagnosis:e1/application/1"},"wh2de4":{"a":"recall","vg":"viro1-diagnosis:e2/recall/2"},"wjkicu":{"a":"recall","vg":"viro1-diagnosis:e6/recall/1"},"11eafhk":{"a":"recall","vg":"viro1-diagnosis:e4/recall/1"},"f7k3vx":{"a":"recall","vg":"viro1-diagnosis:e8/recall/1"},"1ft4m45":{"a":"recall","vg":"viro1-diagnosis:e5/recall/1"},"8ayhbb":{"a":"recall","vg":"viro1-diagnosis:e5/recall/2"},"1efq0d3":{"a":"recall","vg":"viro1-diagnosis:e3/recall/1"},"vfg43k":{"a":"recall","vg":"viro1-diagnosis:e7/recall/1"},"1f6dj0q":{"a":"relationship","vg":"viro1-diagnosis:e8/relationship/1"}},"explRev":"c9c7d417309f"};
